  newest.X=1000;c.TickSocial(1,1800,game.Building.Pieces,true);MigrationChecks.Assert(!c.Gathering,"Welcome evening waits for the newest member to be present");newest.X=8;c.Improvements=1;c.TickSocial(1,1800,game.Building.Pieces,true);MigrationChecks.Assert(!c.Gathering,"Hearth must be built first");c.Improvements=2;c.TickSocial(1,1800,game.Building.Pieces,true);MigrationChecks.Assert(c.Gathering&&c.GatherKind=="A place for someone new","Welcome evening happens before the first Sunday");c.Gathering=false;c.Food=30;
  c.TickSocial(1,23400,game.Building.Pieces,false);MigrationChecks.Assert(!c.Gathering,"Threats prevent gathering");int food=c.Food;c.TickSocial(1,23400,game.Building.Pieces,true);MigrationChecks.Assert(c.Gathering&&c.GatherKind=="Sunday remembrance"&&c.Food==food-3,"Sunday gathering uses one shared meal each");
  c.TickSocial(19,23419,game.Building.Pieces,true);MigrationChecks.Assert(c.GatherLine==1&&c.Memories.Any(m=>m.Kind=="fireside"&&m.Text.Contains("Mara")),"Authored dialogue advances into persistent camp memory");double elapsed=c.GatherElapsed;c.TickSocial(30,23449,game.Building.Pieces,false);MigrationChecks.Assert(c.GatherElapsed==elapsed&&c.Food==food-3,"Threat interruption pauses talk without repeated meal charges");
  c.Gathering=false;c.TickSocial(1,23450,game.Building.Pieces,true);MigrationChecks.Assert(!c.Gathering&&c.Food==food-3,"Same evening cannot replay gathering rewards");c.TickSocial(1,48600,game.Building.Pieces,true);MigrationChecks.Assert(c.Gathering&&c.LastSundayDay==14,"Weekly gathering returns on the following Sunday");
  MigrationChecks.Assert(c.RecordLoss(lost,48601)&&!c.RecordLoss(lost,48602),"Permanent death and memorial are recorded once");MigrationChecks.Assert(c.Survivors.Where(s=>s.Member).All(s=>s.GriefRemaining==10800&&s.GrievingFor==lost.Name)&&lost.State=="dead"&&!c.Gathering,"Every remaining resident mourns the named loss and fire falls silent");
  double grief=n.GriefRemaining;n.Morale=50;string words=c.Conversation(n,"company",48602);double morale=n.Morale;c.Conversation(n,"company",48603);MigrationChecks.Assert(n.Morale==morale&&n.GriefRemaining==grief&&words.Contains("move on"),"Quiet company has cooldown; comfort cannot erase grief");
  var copy=Json.Read<ExpeditionCommunity>(Json.Write(c));copy.Normalize();MigrationChecks.Assert(copy.Losses.Single().Id==lost.Id&&copy.Survivors.First(s=>s.Id==n.Id).GriefRemaining==grief&&copy.Memories.Count==c.Memories.Count&&copy.NewestMember==newest.Id,"Social history, order, grief and deaths survive save/network serialization");
  c.TickSocial(10801,59404,game.Building.Pieces,false);MigrationChecks.Assert(c.Survivors.Where(s=>s.Member).All(s=>s.GriefRemaining==0)&&c.Losses.Count==1,"Mourning eases with active time; memorial remains");
  game.World.Changes.Time=60000;communityFixture=true;SpawnCommunity();Teleport(0,12);n.X=0;n.Z=12;n.Y=player.Position.Y;communityAvatars[n.Id].Mover.Body.Position=NpcPoint(n);n.Health=100;n.Injury=0;HurtCommunity(n,200);MigrationChecks.Assert(n.Downed,"Actual combat downs a settler");TickCommunity(179);MigrationChecks.Assert(n.Member&&n.Downed,"First aid remains possible until rescue deadline");player.Position=NpcPoint(n)+Vector3.Right;game.Life.Bandages=2;CommunityAction(n.Id+"|aid");MigrationChecks.Assert(n.Member&&!n.Downed&&game.Life.Bandages==1,"Actual first aid consumes a dressing and prevents death");
  HurtCommunity(n,200);TickCommunity(180);MigrationChecks.Assert(n.State=="dead"&&c.Losses.Count==2&&!communityAvatars.ContainsKey(n.Id),"Unrescued settler dies and live avatar is removed");TickCommunity(180);SpawnCommunity();MigrationChecks.Assert(n.State=="dead"&&c.Losses.Count==2&&!communityAvatars.ContainsKey(n.Id),"No death duplication or respawn");
